async function fetchAndParseDiff(octokit, owner, repo, pullNumber) {
    info(`Diff Parser: Fetching diff for PR #${pullNumber}`);
    try {
        const { data: files } = await octokit.rest.pulls.listFiles({
            owner,
            repo,
            pull_number: pullNumber,
            per_page: 100,
        });
        const fileDiffs = files.map((file) => ({
            filename: file.filename,
            status: file.status,
            additions: file.additions,
            deletions: file.deletions,
            patch: file.patch || '',
        }));
        const modifiedFiles = fileDiffs.filter((f) => f.status !== 'removed').map((f) => f.filename);
        const totalAdditions = fileDiffs.reduce((sum, f) => sum + f.additions, 0);
        const totalDeletions = fileDiffs.reduce((sum, f) => sum + f.deletions, 0);
        info(`Diff Parser: Found ${fileDiffs.length} files changed (+${totalAdditions}/-${totalDeletions})`);
        return {
            files: fileDiffs,
            modifiedFiles,
            totalAdditions,
            totalDeletions,
        };
    }
    catch (error) {
        const errorMessage = error instanceof Error ? error.message : String(error);
        core_error(`Diff Parser: Failed to fetch diff: ${errorMessage}`);
        throw new Error(`Failed to fetch PR diff: ${errorMessage}`, { cause: error });
    }
}
